function mission(id,title,short,intro,demo,steps,tool,prompt,answer,explanation){const choices=[answer,'Apagar todos os documentos para continuar','Usar um controle que não pertence a esta tarefa'];const correct=(id-1)%3;for(let n=0;n<correct;n++)choices.unshift(choices.pop());return{id,title,short,intro,demo,steps,tool,quiz:{prompt,choices,correct,explanation}};}
const m=mission;
export const migrationCatalog=[
 m(1,'Cadê o Menu Iniciar?','Encontrar aplicativos','O Ubuntu reúne seus programas em Mostrar aplicativos, no rodapé do dock. A pesquisa ajuda a encontrar um programa pelo nome.','Clique em Mostrar aplicativos, pesquise Calculadora e clique no resultado.',[['grid','Abra Mostrar aplicativos.'],['opened','Pesquise Calculadora e abra pela grade.']],'calculator','Onde você encontra a lista de aplicativos?','Em Mostrar aplicativos, no rodapé do dock.','A grade permite procurar e abrir programas, assim como você fazia pelo menu Iniciar.'),
 m(2,'Meus programas favoritos','Usar favoritos','Favoritos são atalhos para abrir programas mais rapidamente. Fixar um favorito não instala nem duplica o aplicativo.','Na grade, clique com o botão direito em Calculadora → Adicionar aos favoritos. Depois abra pelo dock. Se a janela minimizar no primeiro clique, clique novamente para exibi-la.',[['favorite','Adicione Calculadora aos favoritos pelo botão direito.'],['launched','Clique no ícone Calculadora no dock.']],'calculator','O que um favorito representa?','Um atalho para abrir o aplicativo.','O favorito facilita o acesso. O aplicativo continua sendo o mesmo.'),
 m(3,'Minha janela sumiu!','Recuperar uma janela','Minimizar esconde a janela sem fechar seu trabalho. Você pode recuperá-la pelo dock ou por Atividades.','Abra Editor de Texto e clique em Minimizar. Clique no ícone do Editor no dock à esquerda para a janela reaparecer. Você também pode abrir Atividades e clicar na miniatura do Editor.',[['opened','Abra Editor de Texto pela grade.'],['minimized','Minimize essa janela.'],['restored','Recupere a mesma janela pelo ícone do Editor no dock ou pela miniatura em Atividades.']],'editor','Ao minimizar uma janela, o que acontece?','Ela continua aberta e pode ser recuperada.','A janela minimizada mantém seu conteúdo. Fechar e abrir outra janela não é a mesma ação.'),
 m(4,'Onde estão meus documentos?','Sua pasta pessoal','Sua pasta pessoal reúne Documentos, Downloads e outros arquivos. Ela corresponde ao espaço dos seus trabalhos no computador.','Abra Arquivos, clique em Pasta pessoal e depois em Documentos.',[['home','Abra sua Pasta pessoal em Arquivos.'],['documents','Entre na pasta Documentos.']],'files','Onde guardar seus trabalhos pessoais?','Nas pastas da sua pasta pessoal.','Documentos e Downloads são atalhos para locais dentro do seu espaço de usuário.'),
 m(5,'Cadê o disco C:?','Entender os caminhos','O Ubuntu usa uma árvore de pastas iniciada em /. Sua pasta pessoal neste laboratório é /home/aluno. Os separadores são barras /.','Em Arquivos, clique no caminho do cabeçalho e digite /; depois /home; por último /home/aluno. Confirme cada caminho com Enter.',[['root','Abra o caminho /.'],['users','Abra /home.'],['home','Volte para /home/aluno.']],'files','Qual é sua pasta pessoal neste simulador?','/home/aluno.','A raiz / é o início da estrutura. /home/aluno é o espaço deste usuário.'),
 m(6,'Aula e aula são iguais?','Distinguir os nomes','Maiúsculas e minúsculas fazem diferença nos nomes de arquivos do Linux. Aula.txt e aula.txt são dois documentos diferentes.','Em Documentos, abra a pasta {practiceDir}. Abra Aula.txt, leia e feche. Depois abra aula.txt e compare.',[['upper','Na pasta {practiceDir}, abra Aula.txt.'],['lower','Depois abra aula.txt e observe o outro conteúdo.']],'files','Aula.txt e aula.txt podem ser arquivos diferentes?','Sim, a capitalização faz diferença.','Neste cenário os dois nomes coexistem. Observe sempre as letras e o caminho completo.'),
 m(7,'O arquivo ficou escondido','Mostrar arquivos ocultos','Um nome começando com ponto fica oculto na visualização padrão. Mostrar arquivos ocultos não apaga nem altera o documento.','Em Arquivos, abra {practiceDir}. Use Ctrl+H ou botão direito no espaço vazio → Mostrar arquivos ocultos. Abra .atividade.txt.',[['shown','Ative Mostrar arquivos ocultos em Arquivos.'],['opened','Encontre e abra .atividade.txt em {practiceDir}.']],'files','Como reconhecer um arquivo oculto neste exemplo?','Seu nome começa com um ponto.','O arquivo .atividade.txt permanece na pasta. Ctrl+H apenas alterna sua exibição.'),
 m(8,'Qual programa faz essa tarefa?','Conhecer os equivalentes','Writer cria textos, Calc trabalha com planilhas e Impress cria apresentações. Eles fazem parte do LibreOffice.','Na Central, pesquise LibreOffice e abra a ficha. Clique em Conhecer Writer, Conhecer Calc e Conhecer Impress para ver a função de cada um.',[['viewed','Pesquise LibreOffice e abra sua ficha na Central.'],['writer','Consulte Conhecer Writer.'],['calc','Consulte Conhecer Calc.'],['impress','Consulte Conhecer Impress.']],'software','Qual componente cria apresentações?','LibreOffice Impress.','Writer corresponde ao editor de textos, Calc à planilha e Impress ao editor de apresentações.'),
 m(9,'Instalando pela Central','Instalar pela Central','A Central reúne informações sobre aplicativos e permite instalar e abrir os programas do catálogo educativo.','Pesquise Tempo na Central, abra a ficha, clique em Instalar Tempo e depois Abrir Tempo. Se já estiver instalado, confira a ficha e abra.',[['viewed','Abra a ficha de Tempo na Central.'],['installed','Instale Tempo ou confira que já está instalado.'],['opened','Clique em Abrir Tempo.']],'software','O que instalar um aplicativo faz?','Torna o programa disponível para uso.','Baixar, instalar e abrir são ações diferentes. A Central conduz a instalação do catálogo.'),
 m(10,'Baixar é diferente de instalar','Usar um pacote .deb','O pacote baixado fica em Downloads. Abrir o pacote inicia sua instalação; baixar sozinho não instala o programa.','No Firefox, pesquise Chrome, abra Google Chrome para Ubuntu e baixe o pacote. Em Downloads, abra o .deb, instale e abra Chrome.',[['downloaded','Baixe o pacote educativo do Chrome pelo Firefox.'],['package','Em Downloads, abra google-chrome-stable_amd64.deb.'],['opened','Instale e abra Chrome pela Central.']],'firefox','O download sozinho instala o aplicativo?','Não. É necessário abrir o pacote e realizar a instalação.','O arquivo .deb é um pacote para sistemas como Ubuntu. A instalação aqui acontece somente no simulador.'),
 m(11,'Remover o ícone remove o programa?','Atalho e desinstalação','Remover um favorito tira o atalho do dock. Desinstalar remove o programa disponível no computador simulado.','Adicione Tempo aos favoritos pelo botão direito. Remova o favorito e abra Tempo pela grade para conferir. Depois use Central → Instalados → Tempo → Desinstalar.',[['pinned','Adicione Tempo aos favoritos.'],['unpin','Remova Tempo dos favoritos.'],['proved','Abra Tempo pela grade para comprovar que continua instalado.'],['uninstalled','Desinstale Tempo pela Central e confirme.']],'software','Remover um favorito desinstala o aplicativo?','Não. A desinstalação é feita pela Central.','Você abriu Tempo mesmo sem o favorito. Só a desinstalação retirou o aplicativo da grade.'),
 m(12,'Deixe o desktop com a sua cara','Trocar o papel de parede','O papel de parede é a imagem que aparece atrás das janelas. Você pode escolher outra imagem sem mudar seus arquivos.','Abra Configurações pela grade e clique em Aparência. Em Plano de fundo, escolha uma imagem diferente da atual. Role para ver todas as opções.',[['settings','Abra Configurações → Aparência.'],['wallpaper','Escolha um papel de parede diferente do que estava no início da missão.']],'settings','O que muda ao escolher outro papel de parede?','A imagem do fundo do desktop.','Trocar o fundo personaliza a aparência e preserva seus arquivos e aplicativos.'),
 m(13,'Seu nome e seu avatar','Personalizar o perfil','Seu perfil pode mostrar um nome ou apelido e uma imagem escolhida por você. Essas escolhas ficam salvas neste navegador e aparecem na próxima tela de entrada.','Abra Configurações → Perfil. Troque o nome atual por um nome ou apelido, escolha outro avatar e clique em Salvar perfil. Para conferir, recarregue depois de concluir a missão.',[['settings','Abra Configurações → Perfil.'],['name','Mude o nome do perfil e clique em Salvar perfil.'],['avatar','Escolha outro avatar e salve. Você pode salvar nome e avatar juntos.']],'settings','Onde seu nome e avatar serão exibidos depois?','Na tela de entrada deste simulador.','O nome e o avatar ficam salvos neste navegador. Na próxima entrada, eles substituem a apresentação padrão Aluno.')
];
export const installationCatalog=[
 m(1,'Conheça a Central','Pesquisar LibreOffice','A Central permite pesquisar programas e consultar sua descrição antes de instalar. Vamos procurar a suíte de produtividade LibreOffice.','Abra a Central pelo dock e digite LibreOffice ou o início do nome no campo Pesquisar aplicativos. Quando aparecer, clique no resultado LibreOffice.',[['opened','Abra a Central de Aplicativos.'],['searched','Pesquise LibreOffice.'],['viewed','Abra a ficha do LibreOffice.']],'software','O que é o LibreOffice?','Uma suíte com programas para textos, planilhas e apresentações.','O pacote reúne Writer, Calc e Impress. Cada componente possui uma interface própria.'),
 m(2,'Instale o LibreOffice','Instalar a suíte','Instalar a suíte disponibiliza Writer, Calc e Impress. O início do LibreOffice oferece atalhos para criar os três tipos de trabalho.','Na ficha, clique em Instalar LibreOffice e Abrir LibreOffice. Abra Documento de texto, Planilha e Apresentação; feche cada janela quando terminar de observar.',[['installed','Instale LibreOffice ou confira a instalação existente.'],['writer','Abra Writer.'],['calc','Abra Calc.'],['impress','Abra Impress.']],'software','Quais componentes serão usados nesta trilha?','Writer, Calc e Impress.','São os componentes para texto, planilha e apresentação, respectivamente.'),
 m(3,'Encontre uma fonte de download','Pesquisar um programa','Além do catálogo, alguns programas oferecem um pacote em seu site. O endereço ajuda a reconhecer a origem do download.','Abra Firefox, pesquise Chrome e clique no resultado Google Chrome para Ubuntu. Observe o endereço da página simulada.',[['searched','Pesquise Chrome no Firefox.'],['site','Abra Google Chrome para Ubuntu.']],'firefox','O que conferir antes de baixar?','A origem e o endereço da página do programa.','Nesta atividade usamos uma representação local da página oficial. Não é necessário entrar em contas ou serviços reais.'),
 m(4,'Baixar não é instalar','Baixar e instalar .deb','Um download cria um arquivo. O instalador usa esse arquivo para disponibilizar o aplicativo.','Baixe Chrome, clique em Mostrar em Downloads, abra o arquivo .deb e use a Central para instalar e abrir.',[['downloaded','Baixe o pacote educativo do Chrome.'],['package','Abra o pacote em Downloads.'],['opened','Instale ou confira a instalação e abra Chrome.']],'firefox','Qual arquivo inicia essa instalação?','O pacote google-chrome-stable_amd64.deb.','Renomear um documento para .deb não cria um pacote. O simulador reconhece o pacote produzido pelo download.'),
 m(5,'Do Word ao Writer','Escrever e formatar','O Writer é o editor de textos do LibreOffice. A página branca representa seu documento; as ferramentas formatam o texto selecionado.','Abra Writer e crie um documento. Digite um título e um parágrafo sobre sua rotina de estudos. Selecione o título, clique em Negrito e Centralizar.',[['opened','Abra Writer.'],['text','Digite um título e um parágrafo com pelo menos 20 caracteres no total.'],['formatted','Selecione o título e aplique Negrito e Centralizar.']],'writer','Qual aplicativo produz documentos de texto?','LibreOffice Writer.','A formatação é aplicada à seleção ou ao parágrafo atual. Seu texto permanece editável.'),
 m(6,'Salve seu texto','Salvar e reabrir Writer','Salvar registra texto e formatação. Fechar sem salvar pode descartar as últimas mudanças. Vamos conferir reabrindo o arquivo.','No Writer, clique em Salvar e use o caminho sugerido. Feche a janela e abra {writerName} em Documentos → {officeDir}.',[['saved','Salve seu documento como {writerPath}.'],['closed','Feche a janela do Writer.'],['reopened','Em Arquivos, abra {writerName} e confira o texto formatado.']],'writer','O que deve permanecer depois de reabrir?','O texto e a formatação salvos.','Salvar grava o documento no sistema virtual deste navegador. O arquivo pode ser aberto novamente pelo Writer.'),
 m(7,'Do Excel ao Calc','Preencher uma planilha','O Calc organiza dados em células. Cada endereço combina a letra da coluna com o número da linha.','Abra Calc. Preencha A1=Material, B1=Quantidade e C1=Valor. Em A2:A4, escreva Cadernos, Canetas e Pastas. Em B2:B4, digite 10, 20 e 30. Em C2:C4, digite 8, 2 e 4.',[['opened','Abra Calc.'],['table','Preencha os cabeçalhos e os três materiais, quantidades e valores conforme a demonstração.']],'calc','O que o endereço B2 identifica?','A célula na coluna B e linha 2.','A letra indica a coluna e o número indica a linha. Clique na célula para escrever ou corrigir uma informação.'),
 m(8,'Atualize e salve sua planilha','Editar e salvar a planilha','Você pode corrigir uma informação clicando na célula e digitando outro valor. Depois, salve a planilha para guardar a mudança.','Na tabela de materiais, clique em B2 (quantidade de Cadernos) e troque 10 por 15. Clique em Salvar e use o caminho sugerido. Feche Calc e reabra {calcName} em Documentos → {officeDir}.',[['updated','Na célula B2, mude a quantidade de Cadernos para 15.'],['saved','Salve a planilha como {calcPath}.'],['closed','Feche a janela do Calc.'],['reopened','Em Arquivos, reabra {calcName} e confira a quantidade 15.']],'calc','Como guardar a mudança feita na planilha?','Clicando em Salvar antes de fechar.','Editar muda o valor na tela. Salvar grava a nova quantidade para ela continuar no arquivo quando você reabrir.'),
 m(9,'Do PowerPoint ao Impress','Criar uma apresentação','O Impress cria apresentações. As miniaturas organizam os slides, a área central edita o conteúdo e o painel direito escolhe o tema.','Abra Impress. No primeiro slide, escreva Minha escola e um pequeno texto. Clique em Novo slide e escreva Meus estudos com outro texto. Escolha o tema Roxo ou Laranja.',[['opened','Abra Impress.'],['slides','Crie dois slides com títulos e conteúdos.'],['theme','Escolha um tema diferente de Claro.']],'impress','Para que servem as miniaturas à esquerda?','Para selecionar e organizar os slides.','O slide selecionado aparece no centro. Cada slide guarda seu próprio título e conteúdo.'),
 m(10,'Apresente seu trabalho','Salvar e apresentar','O modo de apresentação mostra seus slides para a turma. Salvar registra o trabalho para abrir outra vez.','Salve como {impressPath}. Clique em Apresentar, observe o primeiro slide e avance para o segundo. Use Sair ou Esc para voltar à edição.',[['saved','Salve a apresentação no caminho sugerido.'],['first','Inicie a apresentação e veja o primeiro slide.'],['second','Avance para o segundo slide; depois saia da apresentação.']],'impress','Qual aplicativo cria e apresenta slides?','LibreOffice Impress.','A apresentação mostra os slides em sequência; o arquivo salvo continua disponível para edição.'),
 m(11,'Desinstale um programa','Remover Chrome','Quando um aplicativo não é mais necessário, a Central permite desinstalá-lo. O pacote baixado e seus documentos são itens separados.','Abra Central → Instalados → Google Chrome. Clique em Desinstalar e confirme. Abra Mostrar aplicativos e confira que Chrome saiu da grade.',[['uninstalled','Desinstale Google Chrome pela Central.'],['checked','Abra Mostrar aplicativos e confira a retirada do Chrome.']],'software','Desinstalar Chrome apaga seus trabalhos do LibreOffice?','Não. São documentos e programas diferentes.','A desinstalação retira o aplicativo. Seus documentos do Writer, Calc e Impress são preservados.'),
 m(12,'Reinstale preservando seus trabalhos','Preservar os documentos','Programas e documentos são coisas diferentes. Remover a suíte não apaga os trabalhos que você salvou em Documentos.','Na Central, desinstale LibreOffice. Instale novamente e, em Arquivos, abra seus três trabalhos na pasta {officeDir}. Confira texto, dados da planilha e slides.',[['removed','Desinstale LibreOffice pela Central.'],['installed','Instale LibreOffice novamente.'],['writer','Reabra {writerName}.'],['calc','Reabra {calcName}.'],['impress','Reabra {impressName}.']],'software','O que a reinstalação demonstrou?','Os documentos salvos foram preservados.','Você voltou a abrir os mesmos arquivos depois de reinstalar a suíte. A instalação não substitui o cuidado de salvar seus trabalhos.')
];
migrationCatalog[11].settingsSection='Aparência';migrationCatalog[12].settingsSection='Perfil';
const writerExample={type:'writer',title:'Minha rotina de estudos',body:'Eu estudo informática e aprendo a usar o Ubuntu com meus colegas.'};
const calcExample={type:'calc',headers:['Material','Quantidade','Valor'],rows:[['Cadernos','10','8'],['Canetas','20','2'],['Pastas','30','4']]};
const updatedCalcExample={...calcExample,rows:[['Cadernos','15','8'],['Canetas','20','2'],['Pastas','30','4']],highlight:'B2'};
const impressExample={type:'impress',slides:[{title:'Minha escola',body:'Aprendemos juntos no laboratório de informática.'},{title:'Meus estudos',body:'Escrever no Writer\nCalcular no Calc\nApresentar no Impress'}]};
for(const id of [5,6])installationCatalog[id-1].example=writerExample;
installationCatalog[6].example=calcExample;installationCatalog[7].example=updatedCalcExample;
for(const id of [9,10])installationCatalog[id-1].example=impressExample;
export const terminalCatalog=[
 m(1,'Abra o Terminal','Abrir o Terminal','O Terminal é uma janela onde você dá ordens ao computador escrevendo. Em vez de clicar, você digita um comando (uma palavra curta, em inglês) e aperta Enter. Técnicos de informática usam muito o Terminal porque ele é rápido.','Clique em Mostrar aplicativos, o botão de nove pontinhos no fim do dock, à esquerda. Digite Terminal na pesquisa e clique no ícone preto Terminal. Depois clique dentro da janela preta, digite help e aperte Enter.',[['opened','Abra o Terminal pela grade de aplicativos.'],['help','Clique na janela preta, digite help e aperte Enter.']],'terminal','Como você dá uma ordem ao Terminal?','Digitando um comando e apertando Enter.','O Terminal só executa o comando depois do Enter. O comando help mostra a lista de comandos que você pode usar.'),
 m(2,'Quem sou eu? Onde estou?','Usar whoami e pwd','Dois comandos ajudam você a se localizar. whoami quer dizer “quem sou eu” e mostra o nome do usuário. pwd mostra em qual pasta o Terminal está agora.','Clique dentro do Terminal. Digite whoami e aperte Enter: aparece aluno. Depois digite pwd e aperte Enter: aparece /home/aluno, que é a sua Pasta pessoal.',[['whoami','Digite whoami e aperte Enter.'],['pwd','Digite pwd e aperte Enter.']],'terminal','O que o comando pwd mostra?','A pasta onde o Terminal está agora.','/home/aluno é a sua Pasta pessoal, a mesma que você abre no app Arquivos. No começo da linha, o sinal ~ também quer dizer Pasta pessoal.'),
 m(3,'O que tem aqui?','Listar com ls','O comando ls quer dizer “listar”. Ele mostra tudo o que está dentro da pasta atual. É como olhar a pasta no app Arquivos, só que em texto.','Clique dentro do Terminal. Digite ls (letra L minúscula e letra S) e aperte Enter. Os nomes que terminam com / são pastas: Documentos/, Downloads/, Imagens/…',[['ls','Digite ls e aperte Enter.']],'terminal','No resultado do ls, o que mostra que um nome é uma pasta?','A barra / no final do nome.','Neste Terminal, as pastas aparecem com / no final. Os arquivos aparecem sem a barra, como Boas-vindas.txt dentro de Documentos.'),
 m(4,'Entre em uma pasta','Entrar com cd','O comando cd serve para entrar em uma pasta. É o mesmo que dar dois cliques em uma pasta no app Arquivos.','Digite cd Documentos e aperte Enter. Use D maiúsculo: no Linux, maiúsculas e minúsculas fazem diferença. O começo da linha muda para ~/Documentos. Depois digite ls para ver o que tem dentro.',[['cd','Digite cd Documentos e aperte Enter.'],['ls','Agora digite ls para ver o que tem em Documentos.']],'terminal','O que o comando cd Documentos faz?','Entra na pasta Documentos.','Depois do cd, o começo da linha mostra ~/Documentos. Ele sempre avisa em qual pasta você está.'),
 m(5,'Volte uma pasta','Voltar com cd ..','Dois pontos (..) querem dizer “a pasta de cima”, aquela que guarda a pasta atual. O comando cd .. volta uma pasta, como o botão Voltar do app Arquivos.','Olhe o começo da linha. Se não mostrar ~/Documentos, digite cd Documentos e aperte Enter. Depois digite cd .. (cd, espaço e dois pontos) e aperte Enter. A linha volta a mostrar só ~.',[['inside','Fique dentro de Documentos (a linha mostra ~/Documentos).'],['back','Digite cd .. e aperte Enter para voltar.']],'terminal','Para que serve o comando cd ..?','Para voltar para a pasta de cima.','De ~/Documentos, o cd .. leva de volta para ~, a Pasta pessoal. Digitar só cd também volta direto para a Pasta pessoal.'),
 m(6,'Crie uma pasta','Criar com mkdir','O comando mkdir cria uma pasta nova. O Terminal e o app Arquivos mostram as mesmas pastas: o que você cria em um aparece no outro.','Digite cd Documentos e aperte Enter. Depois digite mkdir {folder} e aperte Enter. Por último, clique no ícone Arquivos no dock, entre em Documentos e procure a pasta {folder}.',[['docs','Entre em Documentos: digite cd Documentos.'],['created','Digite mkdir {folder} e aperte Enter.'],['files','Abra o app Arquivos e entre em Documentos para ver a pasta {folder}.','files']],'terminal','Você criou uma pasta no Terminal. Ela aparece no app Arquivos?','Sim, os dois mostram as mesmas pastas.','O Terminal e o app Arquivos são dois jeitos de mexer nos mesmos arquivos. Um usa texto e o outro usa cliques.'),
 m(7,'Crie um arquivo','Criar com touch','O comando touch cria um arquivo vazio. Vamos criar o arquivo notas.txt dentro da pasta {folder}.','Clique no Terminal. Digite cd {folder} e aperte Enter: a linha passa a mostrar ~/Documentos/{folder}. Depois digite touch notas.txt e aperte Enter. Para conferir, digite ls.',[['inside','Entre na pasta: digite cd {folder}.'],['created','Digite touch notas.txt e aperte Enter.'],['ls','Digite ls para ver o arquivo novo.']],'terminal','O que o comando touch notas.txt faz?','Cria um arquivo vazio chamado notas.txt.','O touch cria o arquivo sem nada escrito. Na próxima missão você vai escrever dentro dele.'),
 m(8,'Escreva e leia um arquivo','Escrever e ler com cat','O comando echo repete um texto. Com o sinal > (maior que), esse texto vai para dentro de um arquivo. O comando cat mostra o que está escrito no arquivo.','Dentro da pasta {folder}, digite echo Eu sei usar o Terminal > notas.txt e aperte Enter. O sinal > fica na tecla do ponto: segure Shift e aperte o ponto. Depois digite cat notas.txt para ler o arquivo.',[['write','Digite echo Eu sei usar o Terminal > notas.txt e aperte Enter.'],['read','Digite cat notas.txt para ler o que você escreveu.']],'terminal','O que o comando cat notas.txt faz?','Mostra na tela o que está escrito no arquivo.','O sinal > guardou o texto do echo dentro de notas.txt, e o cat mostrou esse texto. Cuidado: o > troca tudo o que estava escrito antes.'),
 m(9,'Faça uma cópia','Copiar com cp','O comando cp faz uma cópia de um arquivo. Primeiro você escreve o nome do original e depois o nome da cópia.','Dentro da pasta {folder}, digite cp notas.txt {copy} e aperte Enter. Depois digite ls: os dois arquivos aparecem.',[['copied','Digite cp notas.txt {copy} e aperte Enter.'],['ls','Digite ls para ver o original e a cópia.']],'terminal','No comando cp notas.txt copia.txt, qual nome vem primeiro?','O arquivo original, que será copiado.','O cp segue esta ordem: primeiro o original, depois o nome da cópia. O arquivo notas.txt continua no lugar.'),
 m(10,'Troque o nome','Renomear com mv','O comando mv também serve para trocar o nome de um arquivo. Primeiro você escreve o nome atual e depois o nome novo.','Dentro da pasta {folder}, digite mv {copy} {renamed} e aperte Enter. Depois digite ls: {copy} sumiu e {renamed} apareceu.',[['renamed','Digite mv {copy} {renamed} e aperte Enter.'],['ls','Digite ls para conferir o nome novo.']],'terminal','Depois do mv, o que aconteceu com o nome antigo?','Ele foi trocado pelo nome novo.','O mv não faz cópia: o mesmo arquivo passa a ter o nome novo. Por isso o nome antigo some da lista.'),
 m(11,'Apague com cuidado','Apagar com rm','O comando rm apaga um arquivo. Atenção: no Ubuntu de verdade, o rm apaga na hora e o arquivo não vai para a Lixeira. Por isso, sempre confira o nome antes de apertar Enter.','Dentro da pasta {folder}, digite rm {renamed}. Confira o nome com calma e só então aperte Enter. Depois digite ls: só notas.txt continua na pasta.',[['removed','Digite rm {renamed} e aperte Enter.'],['ls','Digite ls para conferir que só notas.txt ficou.']],'terminal','Por que conferir o nome antes de usar o rm?','Porque o rm apaga o arquivo sem passar pela Lixeira.','No Ubuntu, o arquivo apagado pelo rm não vai para a Lixeira. Confira sempre o nome e a pasta (o começo da linha) antes do Enter.'),
 m(12,'Atalhos que ajudam','Tab, seta e clear','Três truques deixam o Terminal mais fácil: a tecla Tab completa nomes, a seta para cima ↑ traz de volta o último comando e o comando clear limpa a tela.','Digite cd e aperte Enter para voltar ao início (~). Digite cd Doc e aperte a tecla Tab (fica acima do Caps Lock): o nome vira Documentos/. Aperte Enter. Depois digite clear e aperte Enter. Por fim, aperte a seta para cima ↑.',[['tab','Digite cd Doc e aperte Tab para completar o nome.'],['clear','Digite clear e aperte Enter para limpar a tela.'],['history','Aperte a seta para cima ↑ para trazer de volta o último comando.']],'terminal','Para que serve a tecla Tab no Terminal?','Para completar o nome de uma pasta ou arquivo.','Com o Tab você digita menos e erra menos. A seta ↑ repete comandos e o clear limpa a tela sem apagar arquivos.')
];
const tryAgain='Errou? Tudo bem, nada quebra. Leia a mensagem, apague com Backspace e digite de novo.',inFolder='Antes de digitar, olhe o começo da linha: ele precisa mostrar ~/Documentos/{folder}. Se não mostrar, digite cd e aperte Enter (volta ao início ~). Depois digite cd Documentos/{folder}.';
[[[['~','help','Comandos: pwd, ls, cd, mkdir, touch, cat, echo…']]],[[['~','whoami','aluno'],['~','pwd','/home/aluno']]],[[['~','ls','Área de Trabalho/  Documentos/  Downloads/  Imagens/ …']]],[[['~','cd Documentos',''],['~/Documentos','ls','Boas-vindas.txt']],'Dica: digite cd Doc e aperte a tecla Tab. O Terminal completa o nome para você!'],[[['~/Documentos','cd ..',''],['~','pwd','/home/aluno']]],[[['~','cd Documentos',''],['~/Documentos','mkdir {folder}','']],'Escreva o nome igual ao exemplo: letras minúsculas e sem espaço.'],[[['~/Documentos','cd {folder}',''],['~/Documentos/{folder}','touch notas.txt',''],['~/Documentos/{folder}','ls','notas.txt']],inFolder],[[['~/Documentos/{folder}','echo Eu sei usar o Terminal > notas.txt',''],['~/Documentos/{folder}','cat notas.txt','Eu sei usar o Terminal']],'Você pode trocar a frase “Eu sei usar o Terminal” por outra. '+inFolder],[[['~/Documentos/{folder}','cp notas.txt {copy}',''],['~/Documentos/{folder}','ls','{copy}  notas.txt']],inFolder],[[['~/Documentos/{folder}','mv {copy} {renamed}',''],['~/Documentos/{folder}','ls','notas.txt  {renamed}']],inFolder],[[['~/Documentos/{folder}','rm {renamed}',''],['~/Documentos/{folder}','ls','notas.txt']],inFolder],[[['~','cd Doc   ← aperte Tab','fica: cd Documentos/'],['~/Documentos','clear','(a tela fica limpa)'],['~/Documentos','↑  seta para cima','volta: clear']]]].forEach(([lines,tip=tryAgain],index)=>{terminalCatalog[index].example={type:'terminal',lines,tip};});
function prepareMigration(id,c,store,unique,folder){if(id===12)c.initialMigrationWallpaper=store.getSnapshot().preferences.wallpaper;if(id===13)c.initialProfile={...store.getSnapshot().profile};if(id===6||id===7){c.practicePath||=unique(HOME+'/Documentos/Transição Ubuntu');folder(c.practicePath);c.labels={...c.labels,practiceDir:basename(c.practicePath)};for(const[name,text]of [['Aula.txt','Este é o arquivo Aula, com A maiúsculo.'],['aula.txt','Este é outro arquivo: aula, com a minúsculo.'],['.atividade.txt','Você encontrou o arquivo oculto da atividade!']])if(!store.fs.stat(c.practicePath+'/'+name))store.fs.create(c.practicePath+'/'+name,'file',text);}if(id===3){delete c.windowId;}}
function prepareInstallation(id,c,store,unique,folder){c.officePath||=unique(HOME+'/Documentos/Atividades LibreOffice');folder(c.officePath);for(const[kind,name]of [['writer','Meu texto.odt'],['calc','Minha planilha.ods'],['impress','Minha apresentação.odp']])c[kind+'Path']||=unique(c.officePath+'/'+name);c.labels={officeDir:basename(c.officePath),...Object.fromEntries(['writer','calc','impress'].flatMap(kind=>[[kind+'Path',c[kind+'Path']],[kind+'Name',basename(c[kind+'Path'])]]))};}
function observePackage(event,ctx,id){const{type,detail:d}=event,{store,progress:p,mark}=ctx;const idPackage=id===9?'weather':'chrome';if(type==='package:viewed'&&d.packageId===idPackage){mark('viewed');if(store.getSnapshot().installed.includes(idPackage))mark('installed');}if(type==='app:installed'&&d.appId===idPackage)mark('installed');if(idPackage==='chrome'){if(type==='package:downloaded'&&d.packageId==='chrome'&&store.fs.stat(d.path)?.packageId==='chrome')mark('downloaded');if(type==='app:opened'&&d.appId==='software'&&d.packageId==='chrome'&&store.fs.stat(d.path)?.packageId==='chrome'&&p.active.checks.includes('downloaded'))mark('package');if(type==='app:opened'&&d.appId==='chrome'&&p.active.checks.includes('package')&&store.getSnapshot().installed.includes('chrome'))mark('opened');}else if(type==='app:opened'&&d.appId==='weather'&&p.active.checks.includes('viewed')&&store.getSnapshot().installed.includes('weather')){mark('installed');mark('opened');}}
function observeMigration(event,ctx){const{type,detail:d}=event,{store,progress:p,mark,change}=ctx,id=p.active.id,c=p.context,checks=p.active.checks;
 if(id===1){if(type==='shell:menu-opened'&&d.menu==='apps')mark('grid');if(type==='app:opened'&&d.appId==='calculator'&&d.source==='grid'&&checks.includes('grid'))mark('opened');}
 if(id===2){if(type==='favorite:changed'&&d.appId==='calculator'&&d.value&&store.getSnapshot().favorites.includes('calculator'))mark('favorite');if(type==='app:opened'&&d.appId==='calculator'&&d.source==='dock'&&checks.includes('favorite'))mark('launched');}
 if(id===3){
  if(type==='app:opened'&&d.appId==='editor'&&d.windowId){if(c.windowId!==d.windowId)change(next=>{next.context.windowId=d.windowId;next.active.checks=next.active.checks.filter(key=>!['minimized','restored'].includes(key));});mark('opened');}
  if(type==='window:minimized'&&c.windowId&&d.windowId===c.windowId&&checks.includes('opened'))mark('minimized');
  if(type==='window:restored'&&c.windowId&&d.windowId===c.windowId&&['overview','dock'].includes(d.source)&&checks.includes('minimized'))mark('restored');
 }
 if((id===4||id===5)&&type==='files:navigated'){if(d.path===HOME&&(id===5?checks.includes('users'):!checks.includes('documents')))mark('home');if(id===4&&d.path===HOME+'/Documentos'&&checks.includes('home'))mark('documents');if(id===5&&d.path==='/')mark('root');if(id===5&&d.path==='/home'&&checks.includes('root'))mark('users');}
 if(id===6&&type==='file:opened'){if(d.path===c.practicePath+'/Aula.txt')mark('upper');if(d.path===c.practicePath+'/aula.txt'&&checks.includes('upper'))mark('lower');}
 if(id===7){if(type==='files:hidden-changed'&&d.value)mark('shown');if(type==='file:opened'&&d.path===c.practicePath+'/.atividade.txt'&&checks.includes('shown'))mark('opened');}
 if(id===8){if(type==='package:viewed'&&d.packageId==='libreoffice')mark('viewed');if(type==='package:component-viewed'&&d.packageId==='libreoffice'&&checks.includes('viewed'))mark(d.appId);}
 if(id===9||id===10)observePackage(event,ctx,id);
 if(id===11){if(type==='favorite:changed'&&d.appId==='weather'){if(d.value)mark('pinned');else if(checks.includes('pinned')&&store.getSnapshot().installed.includes('weather'))mark('unpin');}if(type==='app:opened'&&d.appId==='weather'&&d.source==='grid'&&checks.includes('unpin')&&store.getSnapshot().installed.includes('weather'))mark('proved');if(type==='app:uninstalled'&&d.appId==='weather'&&checks.includes('proved')&&!store.getSnapshot().installed.includes('weather'))mark('uninstalled');}
 if(id===12){if(type==='settings:section-opened'&&d.section==='Aparência'&&d.windowId)mark('settings');if(type==='preferences:changed'&&d.source==='settings'&&d.section==='Aparência'&&d.windowId&&wallpapers.some(item=>item.id===d.wallpaper)&&d.wallpaper!==c.initialMigrationWallpaper&&store.getSnapshot().preferences.wallpaper===d.wallpaper){mark('settings');mark('wallpaper');}}
 if(id===13){if(type==='settings:section-opened'&&d.section==='Perfil'&&d.windowId)mark('settings');if(type==='profile:changed'&&d.source==='settings'&&d.section==='Perfil'&&d.windowId){const profile=store.getSnapshot().profile;if(profile.name!==d.name||profile.avatar!==d.avatar)return;const newName=profile.name!==c.initialProfile.name,newAvatar=Boolean(avatarById(profile.avatar))&&profile.avatar!==c.initialProfile.avatar;mark('settings');change(next=>{next.active.checks=next.active.checks.filter(key=>key==='name'?newName:key==='avatar'?newAvatar:true);});if(newName&&d.changed?.includes('name'))mark('name');if(newAvatar&&d.changed?.includes('avatar'))mark('avatar');}}

}
function formatted(html){return /<(b|strong)\b|font-weight:\s*(bold|[6-9]00)/i.test(html)&&/text-align:\s*center/i.test(html);}
export function validSchoolTable(cells,firstQuantity=10){return ['A1','B1','C1','A2','A3','A4'].every(key=>String(cells[key]||'').trim())&&['B2','B3','B4','C2','C3','C4'].every(key=>Number.isFinite(Number(String(cells[key]||'').replace(',','.')))&&String(cells[key]||'').trim())&&[firstQuantity,20,30].every((n,i)=>Number(String(cells['B'+(i+2)]).replace(',','.'))===n);}
function observeInstallation(event,ctx){const{type,detail:d}=event,{store,progress:p,mark,change}=ctx,id=p.active.id,c=p.context,checks=p.active.checks;
 const remember=(kind,path)=>change(next=>{next.context[kind+'Path']=path;next.context.labels={...next.context.labels,[kind+'Path']:path,[kind+'Name']:basename(path)};});
 if(id===1){if(type==='app:opened'&&d.appId==='software')mark('opened');if(type==='package:searched'&&queryMatchesName(d.query,'LibreOffice')&&checks.includes('opened'))mark('searched');if(type==='package:viewed'&&d.packageId==='libreoffice'&&checks.includes('opened')&&(checks.includes('searched')||queryMatchesName(d.query,'LibreOffice'))){mark('searched');mark('viewed');}}
 if(id===2){if((type==='app:installed'&&d.appId==='libreoffice'||type==='package:viewed'&&d.packageId==='libreoffice')&&store.getSnapshot().installed.includes('libreoffice'))mark('installed');if(type==='app:opened'&&['writer','calc','impress'].includes(d.appId)&&checks.includes('installed')&&store.getSnapshot().installed.includes('libreoffice'))mark(d.appId);}
 if(id===3&&type==='browser:visited'){try{const url=new URL(d.url);if(/(^|\.)google\.com$/.test(url.hostname)&&url.pathname==='/search'&&url.searchParams.get('q')?.trim())mark('searched');}catch{}if(d.url==='https://www.google.com/chrome/'&&checks.includes('searched'))mark('site');}
 if(id===4)observePackage(event,ctx,10);
 if([5,7,9].includes(id)&&type==='app:opened'&&d.appId==={5:'writer',7:'calc',9:'impress'}[id])mark('opened');
 if(id===5&&type==='office:edited'&&d.kind==='writer'&&checks.includes('opened')){if(officeText('writer',d.payload).length>=20&&/<(?:p|div|br)\b/i.test(d.payload.html))mark('text');if(formatted(d.payload.html)&&checks.includes('text'))mark('formatted');}
 if(id===6){if(type==='office:saved'&&d.kind==='writer'&&matchesGoalPath(d.path,c.writerPath)&&formatted(store.fs.stat(d.path)?.document?.html||'')){remember('writer',d.path);mark('saved');}if(type==='app:closed'&&d.appId==='writer'&&checks.includes('saved'))mark('closed');if(type==='office:opened'&&d.path===c.writerPath&&checks.includes('closed')&&store.fs.stat(d.path)?.officeKind==='writer')mark('reopened');}
 if(id===7&&type==='office:edited'&&d.kind==='calc'&&checks.includes('opened')&&validSchoolTable(d.payload.cells))mark('table');
 if(id===8){if(type==='office:edited'&&d.kind==='calc'&&validSchoolTable(d.payload.cells,15))mark('updated');if(type==='office:saved'&&d.kind==='calc'&&checks.includes('updated')&&matchesGoalPath(d.path,c.calcPath)&&validSchoolTable(store.fs.stat(d.path)?.document?.cells||{},15)){remember('calc',d.path);mark('saved');}if(type==='app:closed'&&d.appId==='calc'&&checks.includes('saved'))mark('closed');if(type==='office:opened'&&d.kind==='calc'&&d.path===c.calcPath&&checks.includes('closed')&&validSchoolTable(store.fs.stat(d.path)?.document?.cells||{},15))mark('reopened');}
 if(id===9&&type==='office:edited'&&d.kind==='impress'&&checks.includes('opened')){if(d.payload.slides.length>=2&&d.payload.slides.slice(0,2).every(slide=>slide.title.trim()&&slide.body.trim()))mark('slides');if(d.payload.theme!=='claro'&&checks.includes('slides'))mark('theme');}
 if(id===10){if(type==='office:saved'&&d.kind==='impress'&&matchesGoalPath(d.path,c.impressPath)&&d.payload.slides.length>=2){remember('impress',d.path);mark('saved');}if(type==='office:presented'&&d.path===c.impressPath&&checks.includes('saved')){if(d.slideIndex===0)mark('first');if(d.slideIndex===1&&checks.includes('first'))mark('second');}}
 if(id===11){if(type==='app:uninstalled'&&d.appId==='chrome'&&!store.getSnapshot().installed.includes('chrome'))mark('uninstalled');if(type==='shell:menu-opened'&&d.menu==='apps'&&checks.includes('uninstalled')&&!store.getSnapshot().installed.includes('chrome'))mark('checked');}
 if(id===12){if(type==='app:uninstalled'&&d.appId==='libreoffice'&&['writer','calc','impress'].every(kind=>store.fs.stat(findGoalPath(store,c[kind+'Path'])||'/')?.officeKind===kind))mark('removed');if(type==='app:installed'&&d.appId==='libreoffice'&&checks.includes('removed'))mark('installed');if(type==='office:opened'&&checks.includes('installed')&&['writer','calc','impress'].includes(d.kind)&&matchesGoalPath(d.path,c[d.kind+'Path'])&&store.fs.stat(d.path)?.officeKind===d.kind){remember(d.kind,d.path);mark(d.kind);}}
}
function freeName(store,dir,name){const dot=name.lastIndexOf('.'),stem=dot>0?name.slice(0,dot):name,extension=dot>0?name.slice(dot):'';let count=1,candidate=name;while(findGoalPath(store,dir+'/'+candidate))candidate=stem+(++count)+extension;return candidate;}
// Names without spaces so students never need quotes; a redo picks treino2, copia2.txt…
function prepareTerminal(id,c,store,unique,folder){const docs=HOME+'/Documentos';if(id<6)return;folder(docs);if(id===6||!c.folderPath)c.folderPath=docs+'/'+freeName(store,docs,'treino');if(id===6){c.labels={folder:basename(c.folderPath)};return;}folder(c.folderPath);c.notePath=findGoalPath(store,c.folderPath+'/notas.txt')||c.folderPath+'/notas.txt';if(id>=9&&!store.fs.stat(c.notePath))store.fs.create(c.notePath,'file','Eu sei usar o Terminal\n');if(id===9||!c.copyName)c.copyName=freeName(store,c.folderPath,'copia.txt');if(id===10||!c.renamedName)c.renamedName=freeName(store,c.folderPath,'resumo.txt');if(id===10&&!findGoalPath(store,c.folderPath+'/'+c.copyName))store.fs.transfer(c.notePath,c.folderPath+'/'+c.copyName,true);if(id===11&&!findGoalPath(store,c.folderPath+'/'+c.renamedName))store.fs.transfer(c.notePath,c.folderPath+'/'+c.renamedName,true);c.labels={folder:basename(c.folderPath),copy:c.copyName,renamed:c.renamedName};}
function observeTerminal(event,ctx){const{type,detail:d}=event,{store,progress:p,mark,change}=ctx,id=p.active.id,c=p.context,checks=p.active.checks,docs=HOME+'/Documentos';
 if(id===1&&type==='app:opened'&&d.appId==='terminal')mark('opened');
 if(id===6&&type==='files:navigated'&&checks.includes('created')&&(d.path===docs||d.path===c.folderPath))mark('files');
 if(id===12){if(type==='terminal:completed')mark('tab');if(type==='terminal:history'&&checks.includes('clear'))mark('history');}
 if(type!=='terminal:command')return;if(id===1)mark('opened');if(d.error)return;
 const{command}=d,paths=d.args.filter(arg=>!arg.startsWith('-')),at=value=>normalize(value,d.from),is=(value,goal)=>matchesGoalPath(at(value),goal),inFolder=d.from===c.folderPath;
 if(id===1&&command==='help')mark('help');
 if(id===2&&['whoami','pwd'].includes(command))mark(command);
 if(id===3&&command==='ls')mark('ls');
 if(id===4){if(command==='cd'&&d.cwd===docs)mark('cd');if(command==='ls'&&d.from===docs&&checks.includes('cd'))mark('ls');}
 if(id===5){if(d.from===docs||d.cwd===docs)mark('inside');if(command==='cd'&&/^\.\.\/?$/.test(paths[0]||'')&&d.cwd===HOME&&d.from===docs)mark('back');}
 if(id===6){if(d.from===docs||d.cwd===docs)mark('docs');const made=command==='mkdir'&&paths.map(at).find(path=>matchesGoalPath(path,c.folderPath)&&store.fs.stat(path)?.type==='folder');if(made){change(next=>{next.context.folderPath=made;next.context.labels={folder:basename(made)};});mark('docs');mark('created');}}
 if(id===7){if(d.cwd===c.folderPath)mark('inside');const made=command==='touch'&&paths.map(at).find(path=>matchesGoalPath(path,c.notePath));if(made){change(next=>{next.context.notePath=made;});mark('created');}if(command==='ls'&&inFolder&&checks.includes('created'))mark('ls');}
 if(id===8){const arrow=d.args.findIndex(arg=>arg==='>'||arg==='>>');if(command==='echo'&&arrow>=0&&is(d.args[arrow+1],c.notePath)&&store.fs.read(at(d.args[arrow+1])).trim())mark('write');if(command==='cat'&&paths.some(path=>is(path,c.notePath))&&checks.includes('write'))mark('read');}
 const copy=c.folderPath+'/'+c.copyName,renamed=c.folderPath+'/'+c.renamedName;
 if(id===9&&command==='cp'&&paths[1]&&is(paths[1],copy)&&findGoalPath(store,copy))mark('copied');
 if(id===10&&command==='mv'&&paths[1]&&is(paths[1],renamed)&&findGoalPath(store,renamed)&&!findGoalPath(store,copy))mark('renamed');
 if(id===11&&command==='rm'&&paths.some(path=>is(path,renamed))&&!findGoalPath(store,renamed))mark('removed');
 if(command==='ls'&&inFolder&&checks.includes({9:'copied',10:'renamed',11:'removed'}[id]))mark('ls');
 if(id===12&&command==='clear')mark('clear');
}
export const kitCatalog=[
 m(1,'Atualize a lista de programas','Usar sudo apt update','No Linux, os programas ficam em repositórios: grandes “lojas” de programas na internet. O comando apt é o instalador do Terminal. Antes de instalar, atualizamos a lista de programas. Como isso mexe no sistema, o comando começa com sudo, que pede permissão de administrador.','Clique em Mostrar aplicativos (os nove pontinhos no fim do dock), pesquise Terminal e abra. Clique na janela preta, digite sudo apt update e aperte Enter. No Ubuntu de verdade, o sudo pede a sua senha, e ela não aparece enquanto você digita. Neste laboratório não precisa de senha.',[['opened','Abra o Terminal pela grade de aplicativos.','terminal'],['update','Digite sudo apt update e aperte Enter.','terminal']],'terminal','O que o comando sudo apt update faz?','Atualiza a lista de programas que podem ser instalados.','O update só atualiza a lista. Ele não instala nada. Depois dele, o apt conhece as versões mais novas dos programas.'),
 m(2,'Instale o VLC pelo Terminal','Instalar com apt install','O VLC é o reprodutor de vídeos mais instalado no Linux: ele abre quase qualquer vídeo ou música. Para instalar pelo Terminal, use sudo apt install e o nome do programa, sempre com letras minúsculas.','No Terminal, digite sudo apt install vlc e aperte Enter. Espere aparecer Pronto!. Depois clique em Mostrar aplicativos, pesquise VLC e clique no ícone do cone laranja.',[['installed','No Terminal, digite sudo apt install vlc e aperte Enter.','terminal'],['opened','Abra o VLC pela grade de aplicativos (ícone do cone laranja).','vlc']],'terminal','Para que serve o sudo no começo do comando?','Para dar permissão de administrador ao comando.','Instalar um programa muda o sistema, por isso precisa de administrador. Sem o sudo, o Terminal responde Permissão negada.'),
 m(3,'Assista a um vídeo no VLC','Abrir com o VLC','O botão direito tem a opção Abrir com. Ela escolhe qual programa vai abrir o arquivo. Vamos abrir um vídeo com o VLC.','Abra Arquivos e clique em Vídeos, na barra lateral. Clique com o botão direito em {video} e escolha Abrir com VLC. No VLC, clique no botão laranja ▶ Reproduzir. Se Abrir com VLC não aparecer, refaça a missão 2.',[['openwith','Em Arquivos → Vídeos, clique com o botão direito em {video} e escolha Abrir com VLC.','files'],['played','No VLC, clique no botão laranja ▶ Reproduzir.','vlc']],'files','Para que serve a opção Abrir com?','Para escolher qual programa abre o arquivo.','O mesmo arquivo pode abrir em programas diferentes. Abrir com deixa você escolher; o vídeo continua igual.'),
 m(4,'Edite uma foto no GIMP','Editar no GIMP','O GIMP é um editor de fotos gratuito, parecido com o Photoshop. Vamos instalar pela Central, deixar uma foto em preto e branco e exportar uma foto nova.','Abra a Central de Aplicativos (a sacola no dock), pesquise GIMP, clique em Instalar GIMP e depois em Abrir GIMP. Clique na foto {image}. No menu Cores, escolha Preto e branco. No menu Arquivo, escolha Exportar como… e clique em Confirmar.',[['installed','Na Central, pesquise GIMP e clique em Instalar GIMP.','software'],['opened','Abra o GIMP e clique na foto {image}.','gimp'],['gray','Clique no menu Cores → Preto e branco.','gimp'],['exported','Clique no menu Arquivo → Exportar como… e depois em Confirmar.','gimp']],'software','Exportar a foto em preto e branco apagou a foto colorida?','Não. A foto nova foi salva com outro nome.','Exportar cria um arquivo novo, terminado em -pb.png. A foto original continua colorida na pasta Imagens.'),
 m(5,'Baixe o VS Code no site','Baixar o VS Code','Alguns programas não estão no repositório do Ubuntu. O Visual Studio Code, editor de código dos programadores, é baixado no site oficial como um pacote .deb.','Abra o Firefox, pesquise VS Code e clique em Visual Studio Code para Ubuntu. Clique em Baixar .deb para Ubuntu e depois em Mostrar em Downloads. Dê dois cliques em code_amd64.deb. Na Central, clique em Instalar Visual Studio Code e depois em Abrir Visual Studio Code.',[['downloaded','No Firefox, pesquise VS Code, abra Visual Studio Code para Ubuntu e clique em Baixar .deb para Ubuntu.','firefox'],['package','Clique em Mostrar em Downloads e abra code_amd64.deb com dois cliques.','files'],['opened','Na Central, clique em Instalar Visual Studio Code e depois em Abrir Visual Studio Code.','software']],'firefox','O que é o arquivo code_amd64.deb?','Um pacote de instalação para Ubuntu.','O .deb é o instalador baixado do site. Baixar só guarda o arquivo; instalar coloca o programa no sistema.'),
 m(6,'Crie sua primeira página','Criar uma página HTML','Os sites são feitos de arquivos .html. O VS Code cria a página pronta para você: é só trocar uma frase pelo seu nome e ver o resultado no navegador.','Abra o VS Code e clique em Novo arquivo HTML. Na linha 5, apague Escreva seu nome aqui e digite o seu nome. Clique em Salvar. Depois clique em ▶ Ver no navegador.',[['created','No VS Code, clique em Novo arquivo HTML.','vscode'],['saved','Na linha 5, troque “Escreva seu nome aqui” pelo seu nome e clique em Salvar.','vscode'],['preview','Clique em ▶ Ver no navegador para ver sua página no Firefox.','vscode']],'vscode','O que é um arquivo .html?','Uma página que o navegador sabe mostrar.','O VS Code mostra o código da página. O Firefox lê esse código e mostra o título e o seu nome formatados.'),
 m(7,'Grave a tela com o OBS Studio','Gravar a tela','O OBS Studio grava a tela do computador. Youtubers e professores usam para fazer vídeos e lives. Primeiro você escolhe o que gravar: isso se chama fonte.','Na Central, pesquise OBS, instale e abra o OBS Studio. Em Fontes, clique em + e escolha Captura de tela. Clique em Iniciar gravação, espere o REC chegar a 0:03 e clique em Parar gravação. Depois clique em Mostrar gravações.',[['installed','Na Central, pesquise OBS, clique em Instalar OBS Studio e depois em Abrir OBS Studio.','software'],['source','Em Fontes, clique em + e escolha Captura de tela.','obs'],['recorded','Clique em Iniciar gravação, espere o REC chegar a 0:03 e clique em Parar gravação.','obs'],['found','Clique em Mostrar gravações e veja o seu vídeo na pasta Vídeos.','obs']],'software','Onde o OBS guardou a gravação?','Na pasta Vídeos.','O OBS salva as gravações na pasta Vídeos, com a data e a hora no nome. Você pode assistir com o VLC.'),
 m(8,'Corte o silêncio no Audacity','Editar um áudio','O Audacity grava e edita áudios, como podcasts e trabalhos com narração. A gravação {audio} tem um silêncio no começo. Vamos tirar esse pedaço.','No Terminal, digite sudo apt install audacity e aperte Enter. Abra o Audacity pela grade e clique em {audio}. Clique no menu Efeito → Truncar silêncio. Depois clique em Arquivo → Exportar como MP3… e em Confirmar.',[['installed','No Terminal, digite sudo apt install audacity e aperte Enter.','terminal'],['opened','Abra o Audacity pela grade e clique em {audio}.','audacity'],['trimmed','Clique no menu Efeito → Truncar silêncio.','audacity'],['exported','Clique no menu Arquivo → Exportar como MP3… e depois em Confirmar.','audacity']],'terminal','O que o Truncar silêncio fez?','Tirou a parte sem som do começo do áudio.','A linha reta da onda era o silêncio. Depois do efeito, o áudio ficou mais curto e o MP3 já começa com a voz.'),
 m(9,'Conheça o seu computador','Usar o fastfetch','Um técnico precisa saber o sistema, o processador e a memória de um computador. O fastfetch mostra tudo isso de uma vez no Terminal.','No Terminal, digite sudo apt install fastfetch e aperte Enter. Depois digite fastfetch e aperte Enter. Procure as linhas OS (sistema), CPU (processador) e Memory (memória).',[['installed','No Terminal, digite sudo apt install fastfetch e aperte Enter.','terminal'],['ran','Digite fastfetch e aperte Enter.','terminal']],'terminal','Na resposta do fastfetch, qual linha mostra a memória RAM?','A linha Memory.','Memory mostra a memória usada e o total, como 1.62 GiB de 3.72 GiB. CPU é o processador e OS é o sistema.'),
 m(10,'Guarde senhas com segurança','Usar o KeePassXC','Usar a mesma senha em todo lugar é perigoso. O KeePassXC guarda suas senhas em um cofre e cria senhas fortes para você. Atenção: neste laboratório, nunca digite suas senhas de verdade.','Na Central, pesquise KeePassXC, instale e abra. Clique em Criar novo cofre. Clique em Nova entrada, escreva Escola no Título, clique em Gerar senha e depois em Salvar.',[['installed','Na Central, pesquise KeePassXC, clique em Instalar KeePassXC e depois em Abrir KeePassXC.','software'],['vault','Clique em Criar novo cofre (ou em Abrir cofre, se ele já existir).','keepassxc'],['entry','Clique em Nova entrada, escreva Escola no Título, clique em Gerar senha e depois em Salvar.','keepassxc']],'software','Por que usar um gerenciador de senhas?','Para ter senhas fortes e diferentes sem decorar todas.','O cofre guarda as senhas fortes que o programa cria. No programa de verdade, você só precisa lembrar a senha mestra do cofre.'),
 m(11,'Crie um ponto de restauração','Usar o Timeshift','Antes de mexer no sistema, o técnico cria um ponto de restauração. Se algo der errado, o Timeshift faz o sistema voltar a como estava. É como salvar o jogo antes de uma fase difícil.','No Terminal, digite sudo apt install timeshift e aperte Enter. Abra o Timeshift pela grade. Clique em Criar e espere o ponto aparecer na lista.',[['installed','No Terminal, digite sudo apt install timeshift e aperte Enter.','terminal'],['opened','Abra o Timeshift pela grade de aplicativos.','timeshift'],['snapshot','Clique em Criar e espere o ponto aparecer na lista.','timeshift']],'terminal','Para que serve um ponto de restauração?','Para o sistema voltar a como estava se algo der errado.','O Timeshift guarda uma cópia do sistema, não dos seus trabalhos. Para os trabalhos, continue guardando cópias em outro lugar.'),
 m(12,'Atualize e faça uma faxina','Atualizar e remover','Programas atualizados deixam o computador mais seguro. E um programa que você não usa pode ser removido. Remover um programa não apaga os seus arquivos.','No Terminal, digite sudo apt upgrade e aperte Enter. Depois digite sudo apt remove vlc e aperte Enter. Por fim, abra Arquivos → Vídeos e confira que {video} continua lá.',[['upgrade','No Terminal, digite sudo apt upgrade e aperte Enter.','terminal'],['removed','Digite sudo apt remove vlc e aperte Enter.','terminal'],['kept','Abra Arquivos → Vídeos e confira que {video} continua lá.','files']],'terminal','Remover o VLC apagou o vídeo?','Não. Programas e arquivos são coisas diferentes.','O apt remove tira só o programa. Seus vídeos, fotos e documentos continuam nas pastas.')
];
const kitTerminal={1:[[['~','sudo apt update','Lendo listas de pacotes... Pronto\nPronto! A lista de programas foi atualizada.']],'sudo = “faça como administrador”. apt = instalador de programas. update = atualizar a lista.'],2:[[['~','sudo apt install vlc','Pronto! Abra o VLC pela grade de aplicativos.']],'Use letras minúsculas: vlc. Se aparecer Permissão negada, faltou o sudo no começo.'],8:[[['~','sudo apt install audacity','Pronto! Abra o Audacity pela grade de aplicativos.']],'No Audacity, a parte reta da onda, marcada como silêncio, é onde não tem som.'],9:[[['~','sudo apt install fastfetch','Pronto! Digite fastfetch para usar.'],['~','fastfetch','OS: Ubuntu 26.04 LTS x86_64\nCPU: Intel(R) Celeron(R) N4500 …\nMemory: 1.62 GiB / 3.72 GiB (43%)']],'OS = sistema. CPU = processador. Memory = memória RAM. Disk = disco.'],11:[[['~','sudo apt install timeshift','Pronto! Abra o Timeshift pela grade de aplicativos.']]],12:[[['~','sudo apt upgrade','Pronto! Seus programas estão atualizados.'],['~','sudo apt remove vlc','Pronto! O programa foi removido.']],'Quer o VLC de volta? Digite sudo apt install vlc.']};
for(const[id,[lines,tip='Errou? Tudo bem, nada quebra. Leia a mensagem, apague com Backspace e digite de novo.']]of Object.entries(kitTerminal))kitCatalog[id-1].example={type:'terminal',lines,tip};
kitCatalog[5].example={type:'code',code:HTML_TEMPLATE,highlight:5,tip:'Troque só o texto entre <p> e </p>. Não apague os sinais < e >.'};
const kitMedia=[['video',HOME+'/Vídeos','video-aula.mp4',{media:'video',src:'assets/media/video-aula.webm'},'Vídeo de exemplo da aula de Linux.'],['image',HOME+'/Imagens','foto-ubuntu.jpg',{media:'image',src:'assets/wallpapers/resolute.webp'},'Foto de exemplo.'],['audio',HOME+'/Música','gravacao.wav',{media:'audio'},'Gravação de voz de exemplo.']];
// Practice files are created once and reused; a student file with the same name is never replaced.
function prepareKit(id,c,store,unique,folder){const need={3:'video',4:'image',8:'audio',12:'video'}[id];for(const[kind,dir,name,extra,text]of kitMedia){if(kind!==need||store.fs.stat(c[kind+'Path']||'/')?.media===kind)continue;folder(dir);const path=store.fs.stat(dir+'/'+name)?.media===kind?dir+'/'+name:dir+'/'+freeName(store,dir,name);if(!store.fs.stat(path))store.fs.create(path,'file',text,extra);c[kind+'Path']=path;}c.labels=Object.fromEntries(kitMedia.filter(([kind])=>c[kind+'Path']).map(([kind])=>[kind,basename(c[kind+'Path'])]));}
const namedPage=html=>!/escreva seu nome aqui/i.test(html)&&/<p>\s*[^<\s][^<]*<\/p>/i.test(html);
function observeKit(event,ctx){const{type,detail:d}=event,{store,progress:p,mark,change}=ctx,id=p.active.id,c=p.context,checks=p.active.checks,installed=appId=>store.getSnapshot().installed.includes(appId);
 const words=type==='terminal:command'&&!d.error?[d.command,...d.args]:[],apt=words[0]==='sudo'&&['apt','apt-get'].includes(words[1]),aptDone=(action,name)=>apt&&words[2]===action&&(!name||words.slice(3).includes(name));
 // Any installation route counts; the steps tell the student which route to practice.
 const install=appId=>{if((aptDone('install',packageById(appId).apt)||type==='app:installed'&&d.appId===appId||type==='package:viewed'&&d.packageId===appId||type==='app:opened'&&d.appId===appId)&&installed(appId))mark('installed');};
 const opened=appId=>{if(type==='app:opened'&&d.appId===appId&&installed(appId)&&checks.includes('installed'))mark('opened');};
 const sawVideos=(type==='files:navigated'||type==='app:opened'&&d.appId==='files')&&d.path===HOME+'/Vídeos';
 if(id===1){if(type==='app:opened'&&d.appId==='terminal'||type==='terminal:command')mark('opened');if(aptDone('update'))mark('update');}
 if(id===2){install('vlc');opened('vlc');}
 if(id===3){if(type==='file:opened-with'&&d.appId==='vlc'&&d.path===c.videoPath)mark('openwith');if(type==='vlc:played'&&d.path===c.videoPath&&checks.includes('openwith'))mark('played');}
 if(id===4){install('gimp');if(type==='gimp:opened'&&store.fs.stat(d.path)?.media==='image'&&checks.includes('installed'))mark('opened');if(type==='gimp:filtered'&&checks.includes('opened'))mark('gray');if(type==='gimp:exported'&&d.gray&&checks.includes('gray'))mark('exported');}
 if(id===5){const deb=Boolean(d.path)&&store.fs.stat(d.path)?.packageId==='vscode';if(type==='package:downloaded'&&d.packageId==='vscode'&&deb)mark('downloaded');if(type==='app:opened'&&d.appId==='software'&&d.packageId==='vscode'&&deb&&checks.includes('downloaded'))mark('package');if(type==='app:opened'&&d.appId==='vscode'&&installed('vscode')&&checks.includes('package'))mark('opened');}
 if(id===6){if(type==='vscode:created'){change(next=>{next.context.htmlPath=d.path;});mark('created');}if(type==='file:changed'&&d.path===c.htmlPath&&checks.includes('created')&&namedPage(store.fs.read(d.path)))mark('saved');if((type==='vscode:previewed'&&d.path===c.htmlPath||type==='browser:visited'&&d.url==='file://'+c.htmlPath)&&checks.includes('saved'))mark('preview');}
 if(id===7){install('obs');if(type==='obs:source-added'&&checks.includes('installed'))mark('source');if(type==='obs:recorded'&&d.screen&&d.seconds>=3&&checks.includes('source')){change(next=>{next.context.recordingPath=d.path;});mark('recorded');}if(sawVideos&&checks.includes('recorded')&&store.fs.stat(c.recordingPath||'/')?.media==='video')mark('found');}
 if(id===8){install('audacity');if(type==='audacity:opened'&&checks.includes('installed'))mark('opened');if(type==='audacity:trimmed'&&checks.includes('opened'))mark('trimmed');if(type==='audacity:exported'&&d.trimmed&&checks.includes('trimmed'))mark('exported');}
 if(id===9){if(aptDone('install','fastfetch')&&installed('fastfetch'))mark('installed');if(words.length===1&&words[0]==='fastfetch'&&checks.includes('installed'))mark('ran');}
 if(id===10){install('keepassxc');if((type==='keepassxc:created'||type==='keepassxc:opened')&&checks.includes('installed'))mark('vault');if(type==='keepassxc:entry-saved'&&/escola/i.test(d.title)&&d.length>=16&&checks.includes('vault'))mark('entry');}
 if(id===11){install('timeshift');opened('timeshift');if(type==='timeshift:created'&&checks.includes('opened'))mark('snapshot');}
 if(id===12){if(aptDone('upgrade'))mark('upgrade');if((aptDone('remove','vlc')||aptDone('purge','vlc'))&&!installed('vlc'))mark('removed');if(sawVideos&&checks.includes('removed')&&store.fs.stat(c.videoPath||'/')?.media==='video')mark('kept');}
}
const distractorsMigration=[['No controle de brilho.','Somente dentro de Documentos.'],['Uma nova instalação do programa.','Uma cópia dos documentos do aplicativo.'],['Ela é desinstalada.','O documento é salvo automaticamente.'],['Somente na raiz do sistema.','Dentro do pacote de instalação.'],['C:\\Users\\Aluno.','/Downloads/aluno.'],['Não, maiúsculas são sempre ignoradas.','Não, um nome com maiúscula é uma pasta.'],['Seu nome termina com .txt.','Seu ícone sempre é vermelho.'],['LibreOffice Calc.','LibreOffice Writer.'],['Cria apenas um arquivo em Downloads.','Transforma todo documento em aplicativo.'],['Sim, basta o download terminar.','Sim, basta renomear qualquer arquivo para .deb.'],['Sim, o ícone é o próprio aplicativo.','Sim, e os documentos também são apagados.'],['Todos os documentos são apagados.','O aplicativo é desinstalado.'],['Somente no Terminal.','No nome de todos os documentos.']];
const distractorsInstallation=[['Apenas um navegador de internet.','Uma atualização do próprio Ubuntu.'],['Word, Excel e PowerPoint.','Firefox, Tempo e Calculadora.'],['Somente a cor do botão Baixar.','Somente o tamanho da janela.'],['Qualquer documento renomeado para .deb.','O arquivo de texto aberto no Writer.'],['LibreOffice Impress.','LibreOffice Calc.'],['Somente o nome do aplicativo.','Somente o título, sem formatação.'],['A célula na linha B e coluna 2.','A segunda planilha do arquivo.'],['Fechando a janela sem salvar.','Mudando o papel de parede.'],['Para instalar novos aplicativos.','Para mostrar arquivos ocultos.'],['LibreOffice Writer.','LibreOffice Calc.'],['Sim, todos os documentos são apagados.','Sim, todos os programas são removidos.'],['Reinstalar recria qualquer arquivo não salvo.','Programa e documento são o mesmo item.']];
const distractorsKit=[['Instala todos os programas de uma vez.','Desliga a internet do computador.'],['Para deixar o comando mais rápido.','Para apagar o programa antigo.'],['Para apagar o arquivo.','Para trocar o nome do arquivo.'],['Sim, a foto colorida foi apagada.','Sim, todas as fotos ficaram em preto e branco.'],['Um vídeo do curso de programação.','Uma página da internet pronta.'],['Um vídeo que o VLC reproduz.','Um programa que se instala sozinho.'],['Na Lixeira.','Dentro do OBS, sem criar arquivo.'],['Aumentou o volume de tudo.','Apagou a gravação inteira.'],['A linha Kernel.','A linha Shell.'],['Para usar a mesma senha em todos os sites.','Para mostrar suas senhas aos colegas.'],['Para deixar a internet mais rápida.','Para apagar vírus sozinho.'],['Sim, todos os vídeos foram apagados.','Sim, o vídeo foi para a Lixeira.']];
const distractorsTerminal=[['Arrastando o ícone para a Lixeira.','Clicando duas vezes no papel de parede.'],['A senha do usuário.','A hora do computador.'],['A cor vermelha do nome.','Um ponto de interrogação no início.'],['Apaga a pasta Documentos.','Cria um documento novo.'],['Para apagar a pasta atual.','Para fechar o Terminal.'],['Não, o Terminal tem pastas separadas.','Só depois de reiniciar o computador.'],['Apaga o arquivo notas.txt.','Abre o arquivo no Writer.'],['Apaga o texto do arquivo.','Copia o arquivo para Downloads.'],['O nome da cópia nova.','O nome da Lixeira.'],['Ficou uma cópia com o nome antigo.','O arquivo foi para a Lixeira.'],['Porque o rm troca o nome do arquivo.','Porque o rm desliga o computador.'],['Para apagar a linha inteira.','Para fechar a janela do Terminal.']];
for(const[catalog,distractors]of [[migrationCatalog,distractorsMigration],[installationCatalog,distractorsInstallation],[terminalCatalog,distractorsTerminal],[kitCatalog,distractorsKit]])for(const mission of catalog){const answer=mission.quiz.choices[mission.quiz.correct],choices=[...distractors[mission.id-1]];choices.splice(mission.quiz.correct,0,answer);mission.quiz.choices=choices;}
export const extraTrails=[{id:'migration',number:2,key:'oslinux.learning.migration.v1',title:'Do Windows ao Ubuntu',finished:'Você reconhece os novos caminhos do Ubuntu e distingue favoritos, pacotes e aplicativos.',description:'As tarefas que você conhece, com os caminhos do Ubuntu.',eyebrow:'WINDOWS → UBUNTU • ADAPTAÇÃO',icon:'assets/learning/windows-ubuntu-icon.png',catalog:migrationCatalog,prepare:prepareMigration,observe:observeMigration},{id:'installlab',number:3,key:'oslinux.learning.install.v1',title:'Instalação de Programas',finished:'Você instalou programas, criou três trabalhos e comprovou sua preservação depois de reinstalar a suíte.',description:'Instale, experimente e crie com Writer, Calc e Impress.',eyebrow:'LIBREOFFICE • APRENDA FAZENDO',icon:'assets/learning/install-programs-icon.png',catalog:installationCatalog,prepare:prepareInstallation,observe:observeInstallation},{id:'terminallab',number:4,key:'oslinux.learning.terminal.v1',title:'Primeiros passos no Terminal',finished:'Você sabe se localizar, criar, copiar, renomear e apagar arquivos usando o Terminal.',description:'Dê ordens ao computador digitando comandos simples.',eyebrow:'TERMINAL • UM COMANDO DE CADA VEZ',icon:'assets/learning/terminal-trail-icon.svg',catalog:terminalCatalog,prepare:prepareTerminal,observe:observeTerminal},{id:'kitlab',number:5,key:'oslinux.learning.kit.v1',title:'Kit essencial do Linux',finished:'Você instalou programas pelo Terminal, pela Central e pelo site, e usou cada um deles.',description:'Instale os programas que todo usuário de Linux usa e faça uma tarefa em cada um.',eyebrow:'PROGRAMAS • TERMINAL, CENTRAL E SITE',icon:'assets/learning/kit-trail-icon.svg',catalog:kitCatalog,prepare:prepareKit,observe:observeKit}];
